{% extends "base.html" %}
{% block title %}Drill{% endblock %}
{% block content %}
<main class="container" id="main-content">
  <h1 class="sr-only">Flashcard Drill</h1>

  <div class="flashcard" id="flashcard" onclick="flipCard()" tabindex="0">
    <div class="flashcard-front">
      <p class="flashcard-label">Question</p>
      <p class="flashcard-text">{{ card.front }}</p>
      <p class="flashcard-hint">Click or press Space to reveal answer</p>
    </div>
    <div class="flashcard-back">
      <p class="flashcard-label">Answer</p>
      <p class="flashcard-text">{{ card.back }}</p>
    </div>
  </div>

  <form method="post" action="/courses/{{ course.slug }}/flashcards/{{ card.id }}/rate" id="rate-form" class="flashcard-ratings" style="display:none;">
    {% if unit_filter %}
    <input type="hidden" name="unit_filter" value="{{ unit_filter }}">
    {% endif %}
    <input type="hidden" name="rating" id="rating-input" value="">
    <input type="hidden" name="card_shown_at" id="card-shown-at" value="">
    <button type="submit" class="rating-btn rating-again" onclick="document.getElementById('rating-input').value='1'">
      <span class="rating-key">1</span> Again
    </button>
    <button type="submit" class="rating-btn rating-hard" onclick="document.getElementById('rating-input').value='2'">
      <span class="rating-key">2</span> Hard
    </button>
    <button type="submit" class="rating-btn rating-good" onclick="document.getElementById('rating-input').value='3'">
      <span class="rating-key">3</span> Good
    </button>
    <button type="submit" class="rating-btn rating-easy" onclick="document.getElementById('rating-input').value='4'">
      <span class="rating-key">4</span> Easy
    </button>
  </form>

  <script>
    document.getElementById('card-shown-at').value = Date.now();
    var flipped = false;
    function flipCard() {
      if (flipped) return;
      flipped = true;
      document.getElementById('flashcard').classList.add('flipped');
      document.getElementById('rate-form').style.display = 'flex';
    }
    document.addEventListener('keydown', function(e) {
      if (e.key === ' ' || e.code === 'Space') {
        e.preventDefault();
        if (!flipped) flipCard();
      }
      if (flipped && e.key >= '1' && e.key <= '4') {
        document.getElementById('rating-input').value = e.key;
        document.getElementById('rate-form').submit();
      }
    });
  </script>
</main>
{% endblock %}

